code.cpp:
class Solution {
public:
    int numSubarrayBoundedMax(vector<int>& nums, int left, int right) {
        return (int)(countLE(nums, right) - countLE(nums, left - 1));
    }
private:
    long long countLE(vector<int>& nums, int bound) {
        long long count = 0;
        int lastInvalid = -1;
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            if (nums[i] > bound) {
                lastInvalid = i;
            } else {
                count += (i - lastInvalid);
            }
        }
        return count;
    }
};
